21fb4b16473dddf250678aa669b61fd6:
query StoragePanelQuery {
  photographer {
    storage {
      totalBytes
      hotBytes
      archivedBytes
      archiveAvailable
      albums {
        albumId
        name
        photoCount
        bytes
        originalBytes
        archivedBytes
        transition
      }
    }
    id
  }
}

6b353e8b7503eedfa6ac9059a6548ced:
query PhotosViewQuery(
  $faceId: ID
  $folderId: ID
) {
  photos(faceId: $faceId, folderId: $folderId) {
    nodes {
      id
      ...PhotoFragment
    }
  }
}

fragment PhotoFragment on PhotoTake {
  id
  eventName
  isPurchased
  previewUrl
  takenAt
  caption
  alternateDescription
}

7251989edfa2dfaaf02a9ea96f773216:
mutation photoUploadAttachMutation(
  $id: ID!
  $files: [PhotoPromiseFileInput!]!
) {
  attachPhotoPromiseFiles(id: $id, files: $files) {
    files {
      id
      uploadUrl
      uploadHeaders
    }
  }
}

84d2099cc4aa3c2efc2a8bc3ccbee185:
query PhotoViewerQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on PhotoTake {
      id
      previewUrl
      alternateDescription
      isPurchased
      takenAt
    }
    id
  }
}

9a799d9216bf40c31339232ddb6099e1:
mutation photoUploadFinishMutation(
  $id: ID!
  $status: PhotoPromiseFileStatus!
) {
  updatePhotoPromiseFileUpdate(id: $id, status: $status) {
    file {
      status
      id
    }
  }
}

b3bb1664a6df453c603d474663920457:
query AdminEventQuery {
  folders {
    totalCount
    nodes {
      id
      name
      photoCount
    }
  }
}

bc5a6686a60762177df862d07e44ac02:
mutation StoragePanelRestoreMutation(
  $id: ID!
) {
  restoreAlbum(id: $id) {
    album {
      albumId
      transition
    }
  }
}

cc8d50971ccfd5f2b83e7e7ccfa71ac1:
mutation StoragePanelArchiveMutation(
  $id: ID!
) {
  archiveAlbum(id: $id) {
    album {
      albumId
      transition
    }
  }
}

cdc39673a687ce9c8747d951db797b3c:
query PhotoPurchaseQuery(
  $photoId: ID!
) {
  node(id: $photoId) {
    __typename
    id
    ... on PhotoTake {
      id
      alternateDescription
      previewUrl
      takenAt
    }
  }
}
